    Next *Node
}

func reverseList(head *Node) *Node {
    var prev *Node
    current := head

    for current != nil {
        // Guardar siguiente nodo
        next := current.Next

        // Invertir el enlace
        current.Next = prev

        // Avanzar
        prev = current
        current = next
    }

    return prev
}
```

## 2. **Recursivo**
Usa la pila de llamadas:

```go
func reverseList(head *Node) *Node {
    if head == nil || head.Next == nil {
        return head
    }

    // Invertir el resto
    newHead := reverseList(head.Next)

    // Cambiar los enlaces
    head.Next.Next = head
    head.Next = nil

    return newHead
}
```

## Comparación:
| Aspecto | Iterativo | Recursivo |
|--------|-----------|----------|
| **Espacio** | O(1) | O(n) - pila de llamadas |
| **Velocidad** | Más rápido | Más lento |
| **Legibilidad** | Clara | Compacta |

**Recomendación**: Usa el enfoque iterativo en producción. El recursivo es elegante pero consume más memoria y puede causar stack overflow en listas muy grandes.

